1	import React, { useState, useCallback, useEffect, useMemo } from "react";
2	import { useSearchParams, useLocation, useNavigate } from "react-router-dom";
3	import { useQuery, useQueryClient } from "@tanstack/react-query";
4	import { useAuth } from "@/hooks/useAuth";
5	import { supabase } from "@/integrations/supabase/client";
6	import AppHeader from "@/components/AppHeader";
7	import AuthDialog from "@/components/AuthDialog";
8	import JobSidebar from "@/components/JobSidebar";
9	import JobDetailView from "@/components/JobDetailView";
10	import JobsOverviewCard from "@/components/JobsOverviewCard";
11	import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
12	import { Card, CardContent } from "@/components/ui/card";
13	import { Badge } from "@/components/ui/badge";
14	import { Button } from "@/components/ui/button";
15	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
16	import { format } from "date-fns";
17	import { toast } from "sonner";
18	import OnboardingWizard from "@/components/OnboardingWizard";
19	
20	export interface PastJob {
21	  id: string;
22	  title: string | null;
23	  job_description: string;
24	  status: string;
25	  created_at: string;
26	  resume_count: number;
27	  jd_analysis_json: any;
28	  dynamic_weights_json: Record<string, number> | null;
29	  inbox_email: string | null;
30	}
31	
32	export interface Result {
33	  id: string;
34	  resume_id: string;
35	  overall_score: number;
36	  missing_skills: string[];
37	  summary: string | null;
38	  interview_questions: any;
39	  filename: string;
40	  file_path: string | null;
41	  candidate_name: string | null;
42	  candidate_email?: string | null;
43	  candidate_phone?: string | null;
44	  candidate_location?: string | null;
45	  // Dynamic scoring fields
46	  hard_fit?: boolean;
47	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
48	  confidence?: number;
49	  strengths_json?: string[];
50	  gaps_json?: string[];
51	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
52	  matched_must_haves?: string[];
53	  missing_must_haves?: string[];
54	  scoring_version?: string;
55	  pending?: boolean;
56	  parsed_json?: any;
57	}
58	
59	export interface ExistingResume {
60	  id: string;
61	  filename: string;
62	  file_path: string | null;
63	  candidate_name: string | null;
64	  created_at: string;
65	}
66	
67	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
68	
69	const ONBOARDING_KEY = "rankora_onboarding_done";
70	
71	const Index = () => {
72	  const { user, profile } = useAuth();
73	  const [searchParams, setSearchParams] = useSearchParams();
74	  const location = useLocation();
75	  const navigate = useNavigate();
76	
77	  // Show onboarding wizard for first-time users
78	  const [showOnboarding, setShowOnboarding] = useState(() => {
79	    if (typeof window === "undefined") return false;
80	    return !localStorage.getItem(ONBOARDING_KEY);
81	  });
82	
83	  const completeOnboarding = useCallback(() => {
84	    localStorage.setItem(ONBOARDING_KEY, "1");
85	    setShowOnboarding(false);
86	  }, []);
87	
88	  const queryClient = useQueryClient();
89	
90	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
91	    queryKey: ["pastJobs", user?.id],
92	    queryFn: async () => {
93	      const { data: jobs } = await supabase
94	        .from("jobs")
95	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
96	        .eq("user_id", user!.id)
97	        .order("created_at", { ascending: false })
98	        .limit(50);
99	      if (!jobs) return [];
100	      return jobs.map((j: any) => ({
101	        id: j.id,
102	        title: j.title,
103	        job_description: j.job_description,
104	        status: j.status,
105	        created_at: j.created_at,
106	        resume_count: j.resumes?.[0]?.count ?? 0,
107	        jd_analysis_json: j.jd_analysis_json,
108	        dynamic_weights_json: j.dynamic_weights_json,
109	        inbox_email: j.inbox_email ?? null,
110	      })) as PastJob[];
111	    },
112	    enabled: !!user,
113	    staleTime: 2 * 60 * 1000,
114	  });
115	
116	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
117	  const [view, setView] = useState<ViewMode>(location.pathname === "/jobs" ? "my-jobs" : "dashboard");
118	  const [results, setResults] = useState<Result[]>([]);
119	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
120	  const [authOpen, setAuthOpen] = useState(false);
121	
122	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
123	
124	  // Sync view with route path
125	  useEffect(() => {
126	    if (location.pathname === "/jobs") {
127	      setView("my-jobs");
128	      setSelectedJobId(null);
129	    }
130	  }, [location.pathname]);
131	
132	  // Handle URL params for deep linking
133	  useEffect(() => {
134	    const jobParam = searchParams.get("job");
135	    const newParam = searchParams.get("new");
136	
137	    if (jobParam && user) {
138	      loadJobData(jobParam);
139	      setSearchParams({}, { replace: true });
140	    } else if (newParam && user) {
141	      handleNewJob();
142	      setSearchParams({}, { replace: true });
143	    }
144	    // eslint-disable-next-line react-hooks/exhaustive-deps
145	  }, [searchParams, user]);
146	
147	  const loadJobData = async (jobId: string) => {
148	    setSelectedJobId(jobId);
149	    setView("job-detail");
150	    try {
151	      // Single query for all resume data (was 2 separate queries)
152	      const { data: allResumes } = await supabase
153	        .from("resumes")
154	        .select("id, filename, file_path, candidate_name, created_at, parsed_json")
155	        .eq("job_id", jobId)
156	        .order("created_at", { ascending: false });
157	
158	      const resumeData = allResumes ?? [];
159	      setExistingResumes(resumeData.map((r) => ({
160	        id: r.id, filename: r.filename, file_path: r.file_path,
161	        candidate_name: r.candidate_name, created_at: r.created_at,
162	      })));
163	
164	      if (resumeData.length === 0) {
165	        setResults([]);
166	        return;
167	      }
168	
169	      const resumeIds = resumeData.map((r) => r.id);
170	      const { data: resultData } = await supabase
171	        .from("results")
172	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
173	        .in("resume_id", resumeIds);
174	
175	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
176	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
177	        const resume = resumeMap.get(r.resume_id);
178	        const parsed = resume?.parsed_json as any;
179	        return {
180	          ...r,
181	          overall_score: r.overall_score ?? 0,
182	          missing_skills: r.missing_skills ?? [],
183	          filename: resume?.filename ?? "Unknown",
184	          file_path: resume?.file_path ?? null,
185	          candidate_name: resume?.candidate_name ?? null,
186	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
187	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
188	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
189	          parsed_json: resume?.parsed_json ?? null,
190	        };
191	      });
192	      // Deduplicate by resume_id — keep highest scoring result per resume
193	      const deduped = new Map<string, Result>();
194	      for (const r of allMerged) {
195	        const existing = deduped.get(r.resume_id);
196	        if (!existing || r.overall_score > existing.overall_score) {
197	          deduped.set(r.resume_id, r);
198	        }
199	      }
200	      const merged = Array.from(deduped.values());
201	      merged.sort((a, b) => b.overall_score - a.overall_score);
202	      setResults(merged);
203	    } catch (err) {
204	      toast.error("Failed to load job data");
205	    }
206	  };
207	
208	  const handleNewJob = () => {
209	    setSelectedJobId(null);
210	    setView("new-job");
211	    setResults([]);
212	    setExistingResumes([]);
213	  };
214	
215	  const handleGoToDashboard = () => {
216	    setSelectedJobId(null);
217	    setView("dashboard");
218	    setResults([]);
219	    setExistingResumes([]);
220	  };
221	
222	  const handleGoToMyJobs = () => {
223	    setSelectedJobId(null);
224	    setView("my-jobs");
225	    setResults([]);
226	    setExistingResumes([]);
227	  };
228	
229	  const handleJobCreated = (job: PastJob) => {
230	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) => [job, ...(prev ?? [])]);
231	    setSelectedJobId(job.id);
232	    loadJobData(job.id);
233	  };
234	
235	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
236	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
237	      (prev ?? []).map((j) => (j.id === jobId ? { ...j, ...updates } : j))
238	    );
239	  };
240	
241	  const handleDeleteJobs = async (jobIds: string[]) => {
242	    await supabase.from("jobs").delete().in("id", jobIds);
243	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
244	      (prev ?? []).filter((j) => !jobIds.includes(j.id))
245	    );
246	  };
247	
248	  const requireAuth = useCallback(() => {
249	    if (!user) { setAuthOpen(true); return true; }
250	    return false;
251	  }, [user]);
252	
253	  return (
254	    <SidebarProvider className="h-svh overflow-hidden">
255	      <JobSidebar
256	        showDashboard={view === "dashboard"}
257	        showMyJobs={view === "my-jobs" || view === "job-detail"}
258	        onNewJob={handleNewJob}
259	        onDashboard={handleGoToDashboard}
260	        onMyJobs={handleGoToMyJobs}
261	        onAuthRequired={() => setAuthOpen(true)}
262	        isAuthenticated={!!user}
263	      />
264	
265	      <SidebarInset className="h-svh overflow-y-auto">
266	        <AppHeader />
267	        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
268	          <SidebarTrigger />
269	          <span className="ml-2 text-sm font-medium text-muted-foreground">Menu</span>
270	        </div>
271	
272	        {/* Dashboard view */}
273	        {view === "dashboard" && user ? (
274	          <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
275	            {/* Hero Section — Greeting + Create Button */}
276	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
277	              <div>
278	                <h1 className="text-2xl font-bold text-foreground">
279	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
280	                </h1>
281	                <p className="text-sm text-muted-foreground mt-1">
282	                  Here's an overview of your hiring activity and insights.
283	                </p>
284	              </div>
285	              <Button size="lg" className="gap-2 shadow-md px-6" onClick={handleNewJob}>
286	                <Plus className="h-4 w-4" /> Create Job
287	              </Button>
288	            </div>
289	
290	            {/* Stats Cards */}
291	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
292	              {[
293	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
294	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
295	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
296	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
297	              ].map((s) => (
298	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
299	                  <CardContent className="px-5 py-4 flex items-center gap-4">
300	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
301	                      <s.icon className="h-5 w-5" />
302	                    </div>
303	                    <div>
304	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
305	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
306	                    </div>
307	                  </CardContent>
308	                </Card>
309	              ))}
310	            </div>
311	
312	            {/* Recent Jobs */}
313	            {pastJobs.length > 0 && (
314	              <div className="space-y-3">
315	                <div className="flex items-center justify-between">
316	                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
317	                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
318	                    View All Jobs →
319	                  </button>
320	                </div>
321	                <div className="grid gap-3">
322	                  {pastJobs.slice(0, 5).map((job) => (
323	                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
324	                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
325	                        <div className="flex items-center gap-3 min-w-0">
326	                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
327	                            <Briefcase className="h-4 w-4 text-primary" />
328	                          </div>
329	                          <div className="min-w-0">
330	                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
331	                            <p className="text-xs text-muted-foreground mt-0.5">
332	                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
333	                            </p>
334	                          </div>
335	                        </div>
336	                        <div className="flex items-center gap-3 shrink-0">
337	                          <Badge
338	                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
339	                            className="text-xs"
340	                          >
341	                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
342	                          </Badge>
343	                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
344	                        </div>
345	                      </CardContent>
346	                    </Card>
347	                  ))}
348	                </div>
349	              </div>
350	            )}
351	
352	            {/* Getting started guide — show only for new users */}
353	            {pastJobs.length === 0 && !loadingPastJobs && (
354	              <Card>
355	                <CardContent className="px-5 py-4 space-y-3">
356	                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
357	                  <div className="space-y-2.5">
358	                    {[
359	                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
360	                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
361	                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
362	                    ].map((item) => (
363	                      <div key={item.step} className="flex items-start gap-3 text-sm">
364	                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
365	                        <span className="text-muted-foreground">{item.text}</span>
366	                      </div>
367	                    ))}
368	                  </div>
369	                </CardContent>
370	              </Card>
371	            )}
372	          </main>
373	        ) : view === "my-jobs" && user ? (
374	          /* My Jobs view — full management */
375	          <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
376	            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
377	              <div className="space-y-1">
378	                <button
379	                  onClick={handleGoToDashboard}
380	                  className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors group mb-1"
381	                >
382	                  <ChevronLeft className="h-3 w-3 group-hover:-translate-x-0.5 transition-transform duration-150" />
383	                  Dashboard
384	                </button>
385	                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
386	                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
387	              </div>
388	              <Button size="lg" className="gap-2 shadow-md px-6 shrink-0" onClick={handleNewJob}>
389	                <Plus className="h-4 w-4" /> Create Job
390	              </Button>
391	            </div>
392	            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
393	          </main>
394	        ) : (
395	          <JobDetailView
396	            selectedJobId={selectedJobId}
397	            selectedJob={selectedJob}
398	            results={results}
399	            setResults={setResults}
400	            existingResumes={existingResumes}
401	            setExistingResumes={setExistingResumes}
402	            onJobCreated={handleJobCreated}
403	            onAuthRequired={() => setAuthOpen(true)}
404	            isAuthenticated={!!user}
405	            pastJobs={pastJobs}
406	            onJobUpdated={handleJobUpdated}
407	            onBack={handleGoToMyJobs}
408	          />
409	        )}
410	      </SidebarInset>
411	
412	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
413	
414	      {user && showOnboarding && (
415	        <OnboardingWizard
416	          open={showOnboarding}
417	          onComplete={completeOnboarding}
418	          onCreateJob={() => { completeOnboarding(); handleNewJob(); }}
419	          onGoToTeam={() => { completeOnboarding(); navigate("/team"); }}
420	          userName={user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0] || "there"}
421	        />
422	      )}
423	    </SidebarProvider>
424	  );
425	};
426	
427	export default Index;
428	
