60	// ─── Job Metadata (for career page) ─────────────────────────────────────────
61	
62	function JobMetadataSection({ jobId }: { jobId: string }) {
63	  const [open, setOpen] = useState(false);
64	  const [location, setLocation] = useState("");
65	  const [department, setDepartment] = useState("");
66	  const [employmentType, setEmploymentType] = useState("Full-time");
67	  const [salaryRange, setSalaryRange] = useState("");
68	  const [expiresAt, setExpiresAt] = useState("");
69	  const [isFeatured, setIsFeatured] = useState(false);
70	  const [saving, setSaving] = useState(false);
71	  // loaded tracks whether DB data has been fetched — blocks form render until then
72	  // to prevent user input being silently overwritten by the async load.
73	  const [loaded, setLoaded] = useState(false);
74	
75	  useEffect(() => {
76	    // Reset loaded state when job changes so we don't show stale data
77	    setLoaded(false);
78	    setLocation("");
79	    setDepartment("");
80	    setEmploymentType("Full-time");
81	    setSalaryRange("");
82	    setExpiresAt("");
83	    setIsFeatured(false);
84	
85	    let cancelled = false;
86	    (async () => {
