/**
 * public-api — Rankora Public REST API
 *
 * Authenticates requests via API key (Authorization: Bearer rk_live_...)
 * Validates key against api_keys table (key_hash = SHA-256 of bearer token).
 *
 * Routes:
 *   GET  /public-api/jobs                     — list jobs for the key owner
 *   GET  /public-api/jobs/:id                 — get single job
 *   POST /public-api/jobs                     — create a job
 *   GET  /public-api/jobs/:id/candidates      — list ranked candidates
 *   GET  /public-api/jobs/:id/results         — alias for candidates
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Authorization, Content-Type",
};

function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
  });
}

function error(message: string, status: number, code?: string): Response {
  return json({ error: message, code: code ?? "error" }, status);
}

/** Convert full API key string → SHA-256 hex digest */
async function hashKey(raw: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(raw);
  const digest = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(digest))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: CORS_HEADERS });
  }

  // ── Auth ─────────────────────────────────────────────────────
  const authHeader = req.headers.get("Authorization") ?? "";
  const match = authHeader.match(/^Bearer\s+(rk_live_[A-Za-z0-9]+)$/);
  if (!match) {
    return error(
      "Missing or invalid API key. Include: Authorization: Bearer rk_live_...",
      401,
      "unauthorized"
    );
  }
  const rawKey = match[1];

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const keyHash = await hashKey(rawKey);
  const { data: keyRecord, error: keyErr } = await supabase
    .from("api_keys")
    .select("id, user_id, revoked")
    .eq("key_hash", keyHash)
    .single();

  if (keyErr || !keyRecord) {
    return error("Invalid API key.", 401, "unauthorized");
  }
  if (keyRecord.revoked) {
    return error("This API key has been revoked.", 401, "key_revoked");
  }

  const userId: string = keyRecord.user_id;

  // Update last_used_at (fire-and-forget)
  supabase
    .from("api_keys")
    .update({ last_used_at: new Date().toISOString() })
    .eq("id", keyRecord.id)
    .then(() => {})
    .catch(() => {});

  // ── Route ────────────────────────────────────────────────────
  const url = new URL(req.url);
  // Strip function prefix from path so we route on the logical path
  // e.g. /public-api/jobs  or  /jobs (when invoked directly)
  const rawPath = url.pathname;
  const path = rawPath.replace(/^\/public-api/, "").replace(/^\/functions\/v1\/public-api/, "");

  // GET /jobs
  if (req.method === "GET" && path === "/jobs") {
    const limit = Math.min(Number(url.searchParams.get("limit") ?? 20), 100);
    const offset = Number(url.searchParams.get("offset") ?? 0);
    const { data, error: dbErr } = await supabase
      .from("jobs")
      .select("id, title, status, created_at, jd_analysis_json")
      .eq("user_id", userId)
      .order("created_at", { ascending: false })
      .range(offset, offset + limit - 1);
    if (dbErr) return error("Failed to fetch jobs.", 500);
    return json({ data, offset, limit });
  }

  // POST /jobs — create job
  if (req.method === "POST" && path === "/jobs") {
    let body: Record<string, unknown>;
    try {
      body = await req.json();
    } catch {
      return error("Invalid JSON body.", 400, "bad_request");
    }
    const title = typeof body.title === "string" ? body.title.trim() : null;
    const job_description = typeof body.job_description === "string" ? body.job_description.trim() : "";
    if (!job_description) {
      return error("job_description is required.", 400, "validation_error");
    }
    const { data, error: dbErr } = await supabase
      .from("jobs")
      .insert({ user_id: userId, title, job_description, status: "pending" })
      .select("id, title, status, created_at")
      .single();
    if (dbErr || !data) return error("Failed to create job.", 500);
    return json(data, 201);
  }

  // Match /jobs/:id  or  /jobs/:id/candidates  or  /jobs/:id/results
  const jobIdMatch = path.match(/^\/jobs\/([0-9a-f-]{36})(\/candidates|\/results)?$/i);
  if (!jobIdMatch) {
    return error(
      `Route not found: ${req.method} ${path}`,
      404,
      "not_found"
    );
  }

  const jobId = jobIdMatch[1];
  const subRoute = jobIdMatch[2] ?? "";

  // Verify ownership
  const { data: job, error: jobErr } = await supabase
    .from("jobs")
    .select("id, title, status, created_at, job_description, jd_analysis_json")
    .eq("id", jobId)
    .eq("user_id", userId)
    .single();
  if (jobErr || !job) {
    return error("Job not found or access denied.", 404, "not_found");
  }

  // GET /jobs/:id
  if (req.method === "GET" && subRoute === "") {
    return json(job);
  }

  // GET /jobs/:id/candidates  or  /jobs/:id/results
  if (req.method === "GET" && (subRoute === "/candidates" || subRoute === "/results")) {
    const { data: resumes } = await supabase
      .from("resumes")
      .select("id, filename, candidate_name, created_at")
      .eq("job_id", jobId);

    const resumeIds = (resumes ?? []).map((r: any) => r.id);
    if (resumeIds.length === 0) return json({ data: [], job_id: jobId });

    const { data: results } = await supabase
      .from("results")
      .select("id, resume_id, overall_score, missing_skills, strengths_json, gaps_json, hard_fit, confidence, matched_must_haves, missing_must_haves")
      .in("resume_id", resumeIds)
      .order("overall_score", { ascending: false });

    const resumeMap = new Map((resumes ?? []).map((r: any) => [r.id, r]));
    const candidates = (results ?? []).map((r: any) => {
      const resume = resumeMap.get(r.resume_id);
      return {
        ...r,
        filename: resume?.filename ?? "Unknown",
        candidate_name: resume?.candidate_name ?? null,
        uploaded_at: resume?.created_at ?? null,
      };
    });

    return json({ data: candidates, job_id: jobId, total: candidates.length });
  }

  return error(`Method not allowed: ${req.method}`, 405, "method_not_allowed");
});

